import { useState, useRef, useMemo } from 'react';
import {
  Plus,
  Edit2,
  Trash2,
  RefreshCw,
  Loader2,
  Search,
  ChevronUp,
  ChevronDown,
  Tag,
  X,
  AlertTriangle,
  Upload,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import I18nInput from '@/components/I18nInput';
import { useCategories, type ICategory } from '@/hooks/useCategories';
import { useProducts } from '@/hooks/useProducts';
import { Image } from '@/components/ui/image';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { batchTranslateI18n } from '@/lib/translate';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import { compressImage } from '@/lib/image-compress';
import SyncStatusBadge from '@/components/SyncStatusBadge';

const ICON_OPTIONS = [
  'Zap', 'Battery', 'Sun', 'RefreshCw', 'BatteryCharging',
  'Lamp', 'Flashlight', 'Lightbulb', 'ShieldCheck', 'Award',
  'Settings', 'Target', 'Factory', 'Box', 'Star',
];

function getIconComponent(name: string) {
  const iconMap: Record<string, React.ComponentType<{ className?: string }>> = {};
  // 动态加载图标，找不到则 fallback 到 Tag
  return iconMap[name] ?? Tag;
}

const EMPTY_FORM: Omit<ICategory, 'id' | 'createdAt'> = {
  slug: '',
  name: createI18nText(''),
  description: createI18nText(''),
  icon: 'Tag',
  iconImage: undefined,
  sortOrder: 1,
  enabled: true,
};

export default function AdminCategoriesPage() {
  const { adminT } = useI18n();
  const { categories, addCategory, updateCategory, deleteCategory, moveCategory } = useCategories();
  const { products, updateProduct, deleteProduct } = useProducts();
  const { markDirty, syncModule, syncJsonFile, syncImagesInData, getStatus } = useSyncService();
  const syncStatus = getStatus('categories');

  const [search, setSearch] = useState('');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState<ICategory | null>(null);
  const [form, setForm] = useState<typeof EMPTY_FORM>(EMPTY_FORM);
  const [iconFileError, setIconFileError] = useState<string | null>(null);

  const [translateAllOpen, setTranslateAllOpen] = useState(false);
  const [pageTranslating, setPageTranslating] = useState(false);
  const pageProgress = useRef({ current: 0, total: 0 });
  const [, setProgressTick] = useState(0);

  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleteMode, setDeleteMode] = useState<'unassign' | 'cascade'>('unassign');
  const [deleting, setDeleting] = useState(false);

  /* ---- 产品数量统计 ---- */
  const productCountMap = useMemo(() => {
    const map: Record<string, number> = {};
    products.forEach((p) => {
      map[p.category] = (map[p.category] ?? 0) + 1;
    });
    return map;
  }, [products]);

  /* ---- 搜索过滤 ---- */
  const filtered = useMemo(() => {
    const kw = search.trim().toLowerCase();
    if (!kw) return categories;
    return categories.filter(
      (c) =>
        c.slug.toLowerCase().includes(kw) ||
        c.name.en.toLowerCase().includes(kw) ||
        c.name.zh.toLowerCase().includes(kw) ||
        c.name.es.toLowerCase().includes(kw) ||
        c.name.ja.toLowerCase().includes(kw),
    );
  }, [categories, search]);

  /* ---- 表单校验 ---- */
  const validate = (): string | null => {
    if (!form.slug.trim()) return 'Slug is required';
    if (!/^[a-zA-Z0-9 _-]+$/.test(form.slug)) {
      return 'Slug can only contain letters, numbers, spaces, underscores, and hyphens';
    }
    if (!form.name.en.trim()) return 'English name is required';
    // slug 唯一性检查
    const duplicate = categories.find(
      (c) => c.slug.toLowerCase() === form.slug.trim().toLowerCase() && c.id !== editing?.id,
    );
    if (duplicate) return 'Slug must be unique';
    return null;
  };

  /* ---- 新增 ---- */
  function openCreate() {
    setEditing(null);
    setForm({
      ...EMPTY_FORM,
      sortOrder: categories.length + 1,
    });
    setDialogOpen(true);
  }

  /* ---- 编辑 ---- */
  function openEdit(cat: ICategory) {
    setEditing(cat);
    setForm({
      slug: cat.slug,
      name: { ...cat.name },
      description: { ...cat.description },
      icon: cat.icon,
      iconImage: cat.iconImage,
      sortOrder: cat.sortOrder,
      enabled: cat.enabled,
    });
    setDialogOpen(true);
  }

  /* ---- 提交 ---- */
  function handleSubmit() {
    const err = validate();
    if (err) {
      toast.error(err);
      return;
    }
    const slug = form.slug.trim();
    if (editing) {
      updateCategory(editing.id, {
        slug,
        name: form.name,
        description: form.description,
        icon: form.icon,
        iconImage: form.iconImage,
        sortOrder: form.sortOrder,
        enabled: form.enabled,
      });
      markDirty('categories');
      toast.success(adminT('admin.categoryUpdated'));
    } else {
      addCategory({
        slug,
        name: form.name,
        description: form.description,
        icon: form.icon,
        iconImage: form.iconImage,
        sortOrder: form.sortOrder,
        enabled: form.enabled,
      });
      markDirty('categories');
      toast.success('Category added');
    }
    setDialogOpen(false);
  }

  /* ---- 图标上传 ---- */
  const handleIconFile = async (file: File) => {
    setIconFileError(null);
    const allowed = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
    if (!allowed.includes(file.type)) {
      setIconFileError('Only JPG/PNG/WEBP/GIF images are allowed');
      return;
    }
    if (file.size > 2 * 1024 * 1024) {
      setIconFileError('Image must be less than 2MB');
      return;
    }
    try {
      const compressed = await compressImage(file, { maxWidth: 256, maxHeight: 256, quality: 0.8 });
      setForm({ ...form, iconImage: compressed });
    } catch {
      setIconFileError('Failed to process image file');
    }
  };

  const removeIconImage = () => {
    setForm({ ...form, iconImage: undefined });
  };

  /* ---- 删除 ---- */
  function confirmDelete(id: string) {
    setDeleteId(id);
  }

  function doDelete() {
    if (!deleteId) return;
    const cat = categories.find((c) => c.id === deleteId);
    const count = cat ? productCountMap[cat.slug] ?? 0 : 0;
    setDeleting(true);

    if (deleteMode === 'unassign' && count > 0) {
      // 将该类目下产品的 category 设为空字符串
      products.forEach((p) => {
        if (p.category === cat?.slug) {
          updateProduct(p.id, { category: '' });
        }
      });
    } else if (deleteMode === 'cascade' && count > 0) {
      // 级联删除所有该类目下的产品
      products.forEach((p) => {
        if (p.category === cat?.slug) {
          deleteProduct(p.id);
        }
      });
    }

    deleteCategory(deleteId);
    markDirty('categories');
    toast.success(
      count > 0
        ? `Category deleted. ${count} product(s) affected.`
        : adminT('admin.categoryDeleted'),
    );
    setDeleteId(null);
    setDeleting(false);
  }

  const deletingCategory = categories.find((c) => c.id === deleteId);
  const deletingProductCount = deletingCategory ? productCountMap[deletingCategory.slug] ?? 0 : 0;

  /* ---- 批量翻译 ---- */
  async function handleTranslateAll() {
    if (categories.length === 0) return;
    setPageTranslating(true);
    pageProgress.current = { current: 0, total: 0 };

    const tasks = categories.flatMap((cat) => [
      { value: cat.name, label: `Name: ${cat.name.en || cat.slug}`, skipIfTranslated: true },
      { value: cat.description, label: `Description: ${cat.name.en || cat.slug}`, skipIfTranslated: true },
    ]);
    pageProgress.current.total = tasks.length;

    const results = await batchTranslateI18n(tasks, (cur, total, label) => {
      pageProgress.current.current = cur;
      pageProgress.current.total = total;
      setProgressTick((n) => n + 1);
      void label;
    });

    // 回写
    let successCount = 0;
    for (let i = 0; i < categories.length; i++) {
      const cat = categories[i];
      const nameResult = results[i * 2];
      const descResult = results[i * 2 + 1];
      const updated: Partial<ICategory> = {};
      if (nameResult && nameResult.success) {
        updated.name = nameResult.value;
      }
      if (descResult && descResult.success) {
        updated.description = descResult.value;
      }
      if (Object.keys(updated).length > 0) {
        updateCategory(cat.id, updated);
        successCount++;
      }
    }

    setPageTranslating(false);
    setTranslateAllOpen(false);
    toast.success(`Translated ${successCount} categories`);
  }

  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.categories') }]}
      />

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Categories Management</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {categories.length} categories · {categories.filter((c) => c.enabled).length} enabled
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              syncModule('categories', 'Categories', async (config) => {
                const dataWithImages = await syncImagesInData(
                  config,
                  categories,
                  'categories',
                  ['iconImage' as any]
                );
                await syncJsonFile(
                  config,
                  'data/categories.json',
                  dataWithImages,
                  'Update categories data'
                );
              })
            }
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setTranslateAllOpen(true)}
            disabled={pageTranslating || categories.length === 0}
            className="text-xs h-9"
          >
            {pageTranslating ? (
              <>
                <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                Translating {pageProgress.current.current}/{pageProgress.current.total}...
              </>
            ) : (
              <>
                <RefreshCw className="size-3.5 mr-1.5" />
                Translate All
              </>
            )}
          </Button>
          <Button onClick={openCreate} className="bg-primary hover:bg-primary/90 text-primary-foreground">
            <Plus className="size-4 mr-2" />
            Add Category
          </Button>
        </div>
      </div>

      {/* 搜索 */}
      <Card className="border-border/40 bg-card">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between gap-3 flex-wrap">
            <CardTitle className="text-base">All Categories</CardTitle>
            <div className="relative w-full sm:w-64">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                type="search"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search categories..."
                className="bg-background pl-9 h-9"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="whitespace-nowrap w-12">#</TableHead>
                  <TableHead className="whitespace-nowrap">Name (EN)</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.slug')}</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.productsCount')}</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.status')}</TableHead>
                  <TableHead className="whitespace-nowrap text-right">{adminT('admin.actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} className="text-center text-muted-foreground py-8">
                      {search ? 'No matching categories' : adminT('admin.noCategoriesYet')}
                    </TableCell>
                  </TableRow>
                ) : (
                    filtered.map((cat, idx) => {
                     const Icon = getIconComponent(cat.icon);
                     return (
                       <TableRow key={cat.id}>
                         <TableCell className="text-muted-foreground text-sm">
                           {cat.sortOrder}
                         </TableCell>
                         <TableCell>
                           <div className="flex items-center gap-3">
                             <div className="w-9 h-9 rounded-md bg-primary/10 flex items-center justify-center shrink-0 overflow-hidden">
                               {cat.iconImage ? (
                                 <Image
                                   src={cat.iconImage}
                                   alt={cat.name.en || cat.slug}
                                   className="w-full h-full object-contain p-1"
                                 />
                               ) : (
                                 <Icon className="size-4 text-primary" />
                               )}
                             </div>
                            <div className="min-w-0">
                              <div className="font-medium truncate max-w-[240px]">
                                {cat.name.en || cat.slug}
                              </div>
                              {cat.description.en && (
                                <div className="text-xs text-muted-foreground truncate max-w-[240px]">
                                  {cat.description.en}
                                </div>
                              )}
                            </div>
                          </div>
                        </TableCell>
                        <TableCell>
                          <code className="text-xs bg-muted px-2 py-0.5 rounded">{cat.slug}</code>
                        </TableCell>
                        <TableCell>
                          <span className="tabular-nums text-sm">
                            {productCountMap[cat.slug] ?? 0}
                          </span>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            <Switch
                              checked={cat.enabled}
                              onCheckedChange={(checked) =>
                                updateCategory(cat.id, { enabled: checked })
                              }
                            />
                            <Badge variant={cat.enabled ? 'default' : 'outline'} className="text-xs">
                              {cat.enabled ? 'Enabled' : 'Disabled'}
                            </Badge>
                          </div>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => moveCategory(cat.id, 'up')}
                              disabled={idx === 0}
                              className="h-8 w-8"
                              title="Move up"
                            >
                              <ChevronUp className="size-3.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => moveCategory(cat.id, 'down')}
                              disabled={idx === filtered.length - 1}
                              className="h-8 w-8"
                              title="Move down"
                            >
                              <ChevronDown className="size-3.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => openEdit(cat)}
                              className="h-8 w-8"
                              title="Edit"
                            >
                              <Edit2 className="size-3.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => confirmDelete(cat.id)}
                              className="h-8 w-8 text-destructive hover:text-destructive"
                              title="Delete"
                            >
                              <Trash2 className="size-3.5" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* 新增/编辑 Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editing ? adminT('admin.editCategory') : adminT('admin.addCategory')}</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">
                Name <span className="text-destructive">*</span>
              </label>
              <I18nInput
                value={form.name}
                onChange={(v) => setForm({ ...form, name: v })}
                placeholder="Enter category name"
              />
            </div>

            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">
                Slug <span className="text-destructive">*</span>
                <span className="text-xs text-muted-foreground font-normal ml-2">
                  Used for URL and product filtering. English only.
                </span>
              </label>
              <Input
                value={form.slug}
                onChange={(e) => setForm({ ...form, slug: e.target.value })}
                placeholder="e.g. Solar Lights"
                disabled={!!editing}
              />
            </div>

            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">
                Description
              </label>
              <I18nInput
                value={form.description}
                onChange={(v) => setForm({ ...form, description: v })}
                placeholder="Brief description (optional)"
                multiline
                rows={2}
              />
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">
                  Icon Pick
                </label>
                <div className="flex flex-wrap gap-1.5 max-h-28 overflow-y-auto p-2 border border-border rounded-md bg-background">
                  {ICON_OPTIONS.map((name) => {
                    const Icon = getIconComponent(name);
                    return (
                      <button
                        key={name}
                        type="button"
                        onClick={() => setForm({ ...form, icon: name, iconImage: undefined })}
                        className={`w-8 h-8 rounded flex items-center justify-center transition-colors ${
                          form.icon === name && !form.iconImage
                            ? 'bg-primary text-primary-foreground'
                            : 'bg-muted hover:bg-accent text-muted-foreground hover:text-foreground'
                        }`}
                        title={name}
                      >
                        <Icon className="size-4" />
                      </button>
                    );
                  })}
                </div>
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">
                  Icon Image
                </label>
                <div className="border border-border rounded-md bg-background p-3 h-28 flex flex-col items-center justify-center">
                  {form.iconImage ? (
                    <div className="relative w-full h-full">
                      <Image
                        src={form.iconImage}
                        alt="Icon preview"
                        className="w-full h-full object-contain rounded"
                      />
                      <Button
                        size="icon"
                        variant="destructive"
                        className="!absolute -top-2 -right-2 z-20 h-6 w-6 rounded-full"
                        onClick={removeIconImage}
                        type="button"
                      >
                        <X className="size-3" />
                      </Button>
                    </div>
                  ) : (
                    <label className="cursor-pointer w-full h-full flex flex-col items-center justify-center text-muted-foreground hover:text-foreground transition-colors">
                      <Tag className="size-5 mb-1" />
                      <span className="text-xs">Upload Image</span>
                      <input
                        type="file"
                        accept="image/jpeg,image/png,image/webp,image/gif"
                        className="hidden"
                        onChange={(e) => {
                          const f = e.target.files?.[0];
                          if (f) handleIconFile(f);
                          e.target.value = '';
                        }}
                      />
                    </label>
                  )}
                </div>
                {iconFileError && (
                  <p className="text-xs text-destructive mt-1">{iconFileError}</p>
                )}
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">
                  Sort Order
                </label>
                <Input
                  type="number"
                  value={form.sortOrder}
                  onChange={(e) =>
                    setForm({ ...form, sortOrder: Number(e.target.value) || 0 })
                  }
                  min={1}
                />
              </div>
            </div>

            <div className="flex items-center justify-between pt-2">
              <div>
                <div className="text-sm font-medium text-foreground">Enabled</div>
                <div className="text-xs text-muted-foreground">
                  Disabled categories are hidden on the frontend
                </div>
              </div>
              <Switch
                checked={form.enabled}
                onCheckedChange={(checked) => setForm({ ...form, enabled: checked })}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleSubmit}
              className="bg-primary hover:bg-primary/90 text-primary-foreground"
            >
              {editing ? adminT('admin.edit') : adminT('admin.addCategory')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* 删除确认 */}
      <AlertDialog open={!!deleteId} onOpenChange={(o) => !o && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertTriangle className="size-5 text-destructive" />
              Delete Category
            </AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete{' '}
              <span className="font-medium text-foreground">
                &ldquo;{deletingCategory?.name.en || deletingCategory?.slug}&rdquo;
              </span>
              ?
              {deletingProductCount > 0 && (
                <div className="mt-4 space-y-3">
                  <div className="p-3 rounded-md bg-destructive/10 border border-destructive/30 text-destructive">
                    <strong>Warning:</strong> {deletingProductCount} product(s) are currently in
                    this category.
                  </div>
                  <div className="text-sm text-foreground font-medium">
                    Choose how to handle these products:
                  </div>
                  <label className="flex items-start gap-3 p-3 rounded-md border border-border bg-background cursor-pointer hover:border-primary/30 transition-colors">
                    <input
                      type="radio"
                      name="deleteMode"
                      checked={deleteMode === 'unassign'}
                      onChange={() => setDeleteMode('unassign')}
                      className="mt-0.5"
                    />
                    <div>
                      <div className="text-sm font-medium text-foreground">
                        Keep products (unassign)
                      </div>
                      <div className="text-xs text-muted-foreground mt-0.5">
                        Products will remain but their category will be cleared.
                      </div>
                    </div>
                  </label>
                  <label className="flex items-start gap-3 p-3 rounded-md border border-border bg-background cursor-pointer hover:border-destructive/40 transition-colors">
                    <input
                      type="radio"
                      name="deleteMode"
                      checked={deleteMode === 'cascade'}
                      onChange={() => setDeleteMode('cascade')}
                      className="mt-0.5"
                    />
                    <div>
                      <div className="text-sm font-medium text-destructive">
                        Delete all products (cascade)
                      </div>
                      <div className="text-xs text-muted-foreground mt-0.5">
                        {deletingProductCount} product(s) will be permanently deleted. This action
                        cannot be undone.
                      </div>
                    </div>
                  </label>
                </div>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{adminT('admin.cancel')}</AlertDialogCancel>
            <AlertDialogAction
              onClick={doDelete}
              disabled={deleting}
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
            >
              {deleting ? (
                <>
                  <Loader2 className="size-4 mr-2 animate-spin" />
                  Deleting...
                </>
              ) : (
                'Delete'
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* 批量翻译确认 */}
      <AlertDialog open={translateAllOpen} onOpenChange={setTranslateAllOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Translate All Categories</AlertDialogTitle>
            <AlertDialogDescription>
              This will translate all category names and descriptions that are missing
              translations (from English to Chinese, Spanish, and Japanese). It may take a while
              depending on the number of categories.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{adminT('admin.cancel')}</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleTranslateAll}
              disabled={pageTranslating}
              className="bg-primary hover:bg-primary/90 text-primary-foreground"
            >
              {pageTranslating ? (
                <>
                  <Loader2 className="size-4 mr-2 animate-spin" />
                  Translating...
                </>
              ) : (
                'Start Translation'
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
